async function startWorkspace(experience=false){demoMode=experience;try{if(experience){if(!window.LEDGER_DEMO_SEED)throw Error('體驗資料尚未載入');api=demoAPI;demoReset();if(!window.LEDGER_MEMORY_ONLY){try{const raw=localStorage.getItem('ledger-browser-v05');if(raw){const candidate=JSON.parse(raw);if(!candidate.ledger||!Array.isArray(candidate.ledger.transactions)||!candidate.planning||!Array.isArray(candidate.planning.items)||!candidate.documents)throw Error();DEMO=candidate}}catch{throw Error('瀏覽器儲存資料無法讀取，請清除ledger-browser-v05或使用後端；未覆寫原資料。')}}}health=await api('/api/health');await reload();const requested=location.hash.slice(1);page=SECTIONS.some(r=>r[0]===requested)?requested:(experience?'dashboard':'intro');el('#connection').textContent=experience?(window.LEDGER_MEMORY_ONLY?'體驗工作階段 · 合成資料':'瀏覽器體驗 · 資料保存在此瀏覽器'):'● 本機後端已連接';draw();if(page==='news')loadNews(false)}catch(error){el('#connection').textContent='尚未連接後端';el('#content').innerHTML=`<div class="ws-head"><div><span class="ws-kicker">WELCOME TO LEDGER</span><h1>先看工作區，再開始整理。</h1><p>${escapeHTML(error.message)}</p></div></div><div class="ws-callout">正式PDF解析需啟動本機後端。也可以先進入完整的合成資料體驗，操作預算、投資、目標與其他頁面。</div><button class="btn primary" id="startExperience">開啟完整網頁體驗 →</button>`;el('#startExperience').onclick=()=>startWorkspace(true)}}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next===page||!SECTIONS.some(r=>r[0]===next))return;if(busy||assistantBusy){location.hash=page;return}if(next!=='news')stopNewsPolling();page=next;draw();if(page==='news')loadNews(false)});
startWorkspace(Boolean(window.LEDGER_DEMO));
